def source(url,scope):return {'url':url,'checked_on':'2026-10-24','scope':scope,'whole_work_read':False}
def c(cid,label,key,priority,works,nodes,gap,action,sources,qualifications=None,person_id=None,coverage='absent_person_and_selected_works'):
 d=counts['people'][key]
 ww=[]
 for wid in works:
  w=next(x for x in d['works'] if x['work_id']==wid)
  ww.append({k:w[k] for k in ['work_id','title','year','first_author_key','verified_in_analysis','verified_dated']})
 return {'id':cid,'label':label,'priority':priority,'coverage_class':coverage,'person_id':person_id,'standalone_node_id':None,'exact_principal_author_key':key,'release_people_all_authorship_in_analysis_count':int(d['release_person']['cited_by_dissertations']),'release_first_author_key_in_analysis_count':d['first_author_in_analysis'],'release_first_author_key_dated_count':d['first_author_dated'],'count_scope':'Exact frozen key, not a merged historical identity; all-authorship release people count is distinct from recomputed first-author union. Named work counts are separate distinct dissertation sets, not added.','named_work_evidence':ww,'existing_related_node_ids':nodes,'specific_content_gap':gap,'recommended_research_and_content':action,'primary_source_checks':sources,'qualifications':qualifications or []}
rows=[]
rows.append(c('hist_foner','Eric Foner: free labour, emancipation and Reconstruction','foner|eric','1-high',['W:foner|reconstruction','W:foner|free soil free labor free men'],['black','newleft','political','w_e_b_du_bois'],'No Foner identity, roster, source or named work in canonical graph. Reconstruction itself is already present: black/reconstruction lists Du Bois and John Hope Franklin, and the new Du Bois biography develops Black political agency. Missing is Foner\'s later reinterpretation and the relationship between antislavery/free-labour ideology, freedom and citizenship.','Research Reconstruction (1988) and Free Soil, Free Labor, Free Men (1970) as contrasting but related interventions; develop the existing Reconstruction strand with explicit historiographical disagreements and the limits of northern antislavery. A person entry is an optional consequence of research, not the initial goal.',[source('https://www.historians.org/person/eric-foner/','AHA institutional biographical essay identifies both original dates, situates Free Soil against revisionist interpretations, and describes Black political agency/economic autonomy in Reconstruction. Named institutional appraisal, not a direct reading of either book.')],['No claim that Black agency or Reconstruction is absent. Do not infer a direct Du Bois-to-Foner influence edge from a shared subject.']))
rows.append(c('hist_cohen','Lizabeth Cohen: labour, New Deal politics and consumer citizenship','cohen|lizabeth','1-high',['W:cohen|making a new deal','W:cohen|consumers republic'],['social','labourhistory','consumption','political','urbanhistory'],'No Lizabeth Cohen identity or work in the graph; no New Deal text found in canonical nodes. Existing consumption entry emphasizes commercial change, households, commodity meanings and earlier European/colonial research. Missing is this major US labour-to-consumption/citizenship connection.','Research Making a New Deal (1990) for workers\' cultural and political formation in Chicago; connect to the 2003 A Consumers\' Republic as explicitly later scholarship on mass consumption, political citizenship and inequality. Add a substantive strand spanning labour/social/political and consumption history before deciding on a standalone biography.',[source('https://www.cambridge.org/core/books/making-a-new-deal/E27B0C6C73EF62AABBDA46D6015AB2CC','Publisher description and contents: workers, culture, New Deal Democrats and CIO unionists. Listing identifies 1990 first printing separately from later editions.'),source('https://www.penguinrandomhouse.com/books/29448/a-consumers-republic-by-lizabeth-cohen/','Publisher author/title, 2003 paperback metadata and description connecting consumption, citizenship and inequality. No book text read.')],['Frozen title says A Consumer’s Republic; publisher title is A Consumers’ Republic. Preserve corpus key/count as observed rather than silently editing release data.','2003 is later scholarship beyond the principal 1920–2000 map boundary; label it explicitly.']))
rows.append(c('hist_rodgers','Daniel T. Rodgers: transnational social policy and reform','rodgers|daniel t','1-high',['W:rodgers|atlantic crossings','W:rodgers|age of fracture'],['atlantic','global','political','intellectualhistory'],'No Rodgers identity or work. Atlantic history is developed around slavery, trade, empire and diaspora; global has comparison and circulation but lacks Rodgers\'s named transatlantic reform/social-policy research programme.','Research Atlantic Crossings (1998), its methods and reception, to add circulation/adaptation of reform ideas and institutions to Atlantic/global and political history. Include later critiques of the book\'s geographical, racial and imperial limits; Age of Fracture (2011) is a separate optional later intellectual-history topic.',[source('https://history.princeton.edu/people/daniel-rodgers','Author\'s institutional biography verifies Atlantic Crossings (1998) and Age of Fracture (2011).'),source('https://history.princeton.edu/about/publications/atlantic-crossings-social-politics-progressive-age','Institutional book description details international reform networks and social-policy adaptations. This ISBN listing dates a 2000 edition, distinct from the 1998 original in the faculty biography.'),source('https://doi.org/10.1017/S1537781423000221','2023 authored historiographical roundtable abstract and visible extract identify transnational-turn reception and new questions about colonialism, race and gender; whole roundtable not read.')],['Do not call transnational or Atlantic history absent. Do not equate Rodgers\'s Euro-American network with all global reform history.']))
rows.append(c('hist_bederman','Gail Bederman: race, masculinity and civilization','bederman|gail','1-high',['W:bederman|manliness and civilization','W:bederman|manliness civilization'],['gender','culture','racial_formation','intersectionality'],'No Bederman person or work. gender/masculinity is currently Bourke and Dismembering the Male; broader gender/race scholarship exists through Higginbotham and colonial categories. Missing is the specific US historical analysis of masculinity formed through racialized civilization discourse.','Research Manliness and Civilization (1995) to broaden the masculinity strand beyond war and Britain, identifying the conjunction of race, sexuality, gender and national power through its specific cases. Keep US cultural-historical inquiry distinct from Omi/Winant\'s general racial-formation framework.',[source('https://press.uchicago.edu/ucp/books/book/chicago/M/bo3683791.html','Official publisher author/title, copyright 1995, description and contents, including Wells, Roosevelt, G. Stanley Hall and Gilman. Later format date is not a new original.')],['Two release title keys are variants (and/ampersand); 103 and 46 dated sets must not be summed as a recovered book total.','Gender and racial analysis already exist; this is a missing historian/intervention and a thin regional strand.']))
rows.append(c('hist_ngai','Mae M. Ngai: immigration restriction, legality and citizenship','ngai|mae m','1-high',['W:ngai|impossible subjects','W:ngai|architecture of race in american immigration law|a'],['racial_formation','political','cdn_immigration_ethnicity','settler_colonialism'],'No Ngai person or work; substring Ngai occurs only inside an unrelated findingaids URL. Canadian immigration/race history is substantive, but US immigration restriction and the historical production of legal/illegal belonging lack this named intervention.','Research the 1999 immigration-law article as an in-period intervention, then Impossible Subjects (2004) as explicitly later scholarship; develop migration/citizenship/racialization content with the legal making of categories, not just an author roster addition. Comparative Canadian connections require separate evidence.',[source('https://history.columbia.edu/person/ngai-mae/','Author\'s institutional research profile and bibliography verify identity, immigration/citizenship/nationalism remit, and Impossible Subjects (2004).'),source('https://www.degruyterbrill.com/document/doi/10.1515/9781400850235-fm/pdf','Publisher-distributed front-matter search extract identifies first printing 2004, first paperback 2005 and new-foreword edition 2014; metadata only, PDF book unread.')],['2004 publication must remain later scholarship, not a field-origin date. No present-day legal-policy guidance or claims about the book\'s complete argument.']))
rows.append(c('hist_benton','Lauren Benton: imperial legal pluralism and uneven sovereignty','benton|lauren a','1-high',['W:benton|search for sovereignty','W:benton|law and colonial cultures'],['global','post','spatialhistory','settler_colonialism','indigenous'],'No Benton person, work or named contribution; no legal pluralism or jurisdiction substring in canonical nodes. Existing sovereignty and colonial analysis is substantive, but the comparative history of overlapping imperial jurisdictions and uneven legal space is missing.','Research Benton\'s legal-pluralism and legal-geography interventions to add a methods/debate strand across global, colonial and spatial history. Assess Indigenous actors\' legal practices and competing jurisdictions without reducing them to European state diffusion. This is content research, not an automatic new legal-history field node.',[source('https://www.cambridge.org/core/books/law-and-colonial-cultures/5DE1BB3C38E1F258F57ACC6A437BACF2','Publisher description and contents identify comparative colonial legal orders and Indigenous legal participation; current page dates print format December 2001.'),source('https://lawcat.berkeley.edu/record/81694?ln=en','Institutional library catalog identifies author, title and 2002 imprint.'),source('https://www.cambridge.org/core/books/search-for-sovereignty/1FCB3767F56B64879CF13618A139866A','Publisher author/title, description and contents identify legal geography, corridors/enclaves and uneven imperial authority; print listing dates November 2009.')],['Both principal corpus dates (2002, 2010) differ from publisher format dates (2001, 2009). These are observations to resolve with original front matter, not corrections accepted by this review.','Most books are after 2000; explicitly label later research. No whole-book reading or new legal claim.']))
rows.append(c('hist_jacobson','Matthew Frye Jacobson: changing whiteness and immigrant racialization','jacobson|matthew f','2-high',['W:jacobson|whiteness of a different color','W:jacobson|barbarian virtues'],['racial_formation','cdn_immigration_ethnicity','culture','languages_of_class'],'No Matthew Frye Jacobson identity or work. Claire Jacobson is a different person, a Lévi-Strauss translator in an existing source. Race/whiteness is not absent: Omi/Winant, Perry and Roediger are covered. Missing is this specific US historical account of immigrant groups\' shifting racial classification.','Research Whiteness of a Different Color (1998) with historiographical criticism of whiteness studies; connect political/legal classification, immigration and imperial cultural politics. Add a defined historical problem and its evidence, preserving differences from Roediger\'s working-class formation.',[source('https://history.yale.edu/people/matthew-jacobson','Author\'s institutional profile verifies full identity and 1998/2000 books, research on immigration, citizenship, race and expansion.'),source('https://www.jstor.org/stable/j.ctvjk2w15','Harvard University Press book record, description and contents distributed through JSTOR: 1998, author, title, contingent racial categories and civic assimilation; text unread.')],['Principal key dated count149 is not all variants; the separate frye jacobson key must not be added.','Do not claim a new concept of social construction of race.']))
rows.append(c('hist_berlin','Ira Berlin: historically variable slave societies and emancipation research','berlin|ira','2-high',['W:berlin|many thousands gone','W:berlin|slaves without masters'],['black','atlantic','labourhistory','quant','capitalismdebates'],'No Ira Berlin identity or work. Slavery scholarship is already substantial through Du Bois, Williams, Gutman, Fogel/Engerman, Johnson, Baptist and others. Missing is Berlin\'s comparative temporal/regional reconstruction of slavery and the collaborative documentary-research tradition of emancipation.','Research Many Thousands Gone (1998) and Slaves Without Masters (1974), plus the Freedmen and Southern Society Project\'s collaborative editorial practice, to distinguish kinds and changes of slave societies from aggregate economics and single plantation narratives. Verify specific conceptual distinctions in book introductions before drafting.',[source('https://koha-public.mdah.ms.gov/cgi-bin/koha/opac-detail.pl?biblionumber=2454','Mississippi Department of Archives and History catalog verifies Ira Berlin, exact title and 1998 imprint of Many Thousands Gone; bibliographic metadata only.'),source('https://www.columbia.edu/cu/newrec/2421/tmpl/story.9.html','Contemporaneous Columbia institutional announcement identifies Berlin, Many Thousands Gone and publisher for 1999 Bancroft recognition. Prize is context, not a quality score.'),source('https://arhu.umd.edu/news/historian-ira-berlin-challenges-emancipation-assumptions','Institutional page republishes John David Smith\'s named reading of the later Long Emancipation, and identifies Slaves Without Masters/Many Thousands Gone. Used as a research lead for emancipation, not passage evidence for the earlier books.')],['No claim that slavery or Black agency is absent. All editorial-team credits for documentary volumes need independent checking; release first-author keys cannot establish sole authorship.']))
rows.append(c('hist_kelley','Robin D. G. Kelley: Black working-class political culture and everyday resistance','kelley|robin d','2-high',['W:kelley|race rebels','W:kelley|hammer and hoe','W:kelley|freedom dreams'],['black','labourhistory','newleft','culturalstudies','settler_colonialism'],'Not a wholly absent name: source p4b_kelley_2017 records The Rest of Us and a source-mediated settler-colonial critique. No shared person record, roster or principal books. The Black labour/radical and popular-cultural intervention is missing.','Research Hammer and Hoe (1990) and Race Rebels (1994) to develop Black radical political culture and everyday resistance across Black, labour, social and cultural history. Freedom Dreams (2002) can add an explicitly later strand on political imagination; preserve the existing 2017 source without treating it as coverage of the earlier books.',[source('https://history.ucla.edu/person/robin-d-g-kelley/','Author\'s institutional bibliography verifies Race Rebels (1994), Hammer and Hoe (1990), full identity and publication distinctions.'),source('https://www.simonandschuster.com/books/Race-Rebels/Robin-Kelley/9780684826394','Official publisher description and visible chapter excerpt support this research priority on everyday Black working-class resistance; listing is the June 1996 paperback, not the original 1994 date. Whole book unread.')],['Robert Kelley is another existing person and must not be reused.','Black radicalism and resistance already have independent roots in existing nodes; do not invent a new founding narrative.'],coverage='source_only_name_missing_core_scholarship'))
rows.append(c('hist_mcgirr','Lisa McGirr: social history of grassroots conservatism','mcgirr|lisa','2-high',['W:mcgirr|suburban warriors','W:mcgirr|war on alcohol'],['political','social','urbanhistory','newleft'],'No McGirr person or book. Existing conservatism mentions concern Kolko\'s critique of Progressive reform and other regional contexts; no sustained US grassroots New Right historiography appears. Missing is social history applied to conservative mobilization as a historical object.','Research Suburban Warriors (2001) as explicitly later scholarship on postwar conservative organizing, institutions, religion and suburban community. Add a political/social-history strand whose historical subjects extend beyond the Left; it need not be a separate school or a new influence arrow.',[source('https://history.fas.harvard.edu/people/lisa-mcgirr','Author\'s institutional profile verifies identity, the book\'s 2001/2015 editions, and its subject of grassroots conservative politics/social and regional bases.'),source('https://www.si.edu/object/suburban-warriors-origins-new-american-right-lisa-mcgirr:siris_sil_682560','Smithsonian library record verifies original 2001 and contents, including Goldwater organizing, popular conservatism and evangelicalism; metadata only.')],['2001 publication is beyond the principal period boundary; label later scholarship. History of a conservative movement is not an allegation about the historian\'s politics.']))
rows.append(c('hist_cooper','Frederick Cooper: critical concepts and alternatives to empire-to-nation teleology','cooper|frederick','2-development',['W:cooper|colonialism in question'],['post','social','political','africanhist','labourhistory','languages_of_class'],'Cooper is already a shared person and appears extensively in rosters, strands and mediated relationships on African labour, colonial categories and Tensions of Empire. The post roster itself explicitly says his later criticism requires a separate dated claim. Colonialism in Question (2005) is absent by title from the graph.','Develop the missing 2005 conceptual intervention, especially how identity, globalization, modernity and empire/nation categories are questioned. Preserve the existing contributions and scope; include Rogers Brubaker\'s coauthorship of the identity chapter. A later critical strand is a higher content priority than a generic biography promotion.',[source('https://www.ucpress.edu/books/colonialism-in-question/pdf','Official publisher identifies 2005, author, description and contents, including Identity with Rogers Brubaker. Supports research priorities on conceptual categories and alternatives to inevitable empire-to-nation history; no book text read.')],['This does not mean Cooper, colonial labour or metropole-colony scholarship is missing.','2005 is explicitly later scholarship. A criticism edge needs exact targets and passage-level evidence, not just a publisher description.'],person_id='frederick_cooper',coverage='substantial_roster_and_strand_coverage_specific_later_intervention_missing'))
rows.append(c('hist_roediger','David R. Roediger: race/class formation beyond a single roster sentence','roediger|david r','3-development',['W:roediger|wages of whiteness','W:roediger|working toward whiteness'],['languages_of_class','labourhistory','racial_formation','cdn_immigration_ethnicity'],'Existing david_roediger is a contributor in languages_of_class, with Wages of Whiteness (1991) and source loc_roediger_wages_1991. An Adele Perry review edge mentions his concept. So Wages is represented; current coverage remains a short publisher-scoped contribution, with no sustained methodological treatment or dedicated labour/racial-formation strand.','Deepen the already accepted race/class/whiteness question through primary introduction reading and named critics. Develop the historical evidence, limits and disagreements in relation to Jacobson and migration studies. Working toward Whiteness (2005) is a separately missing later work, not a reason to call Wages absent.',[source('https://www.versobooks.com/products/2966-the-wages-of-whiteness','Official current-edition title, author and description read. Supports a research focus on white worker identity and race/class; displayed edition is 2022, not the first 1991 publication recorded by existing source loc_roediger_wages_1991. Body unread.')],['Not a work-omission correction: Wages already appears in roster prose/source and must be retained.','Later work title/date not independently checked in this review; keep Working toward Whiteness as a corpus-discovered research lead, not ready-to-accept chronology.'],person_id='david_roediger',coverage='represented_work_thin_substantive_treatment'))
